// Does Math.floor(num/100) ever differ from the exact integer floor?
let wrong = 0
const examples = []
for (let c = 1; c <= 300000; c += 1) {
  for (let p = 1; p <= 100; p += 1) {
    const num = c * p
    let q = 0
    while ((q + 1) * 100 <= num) q += 1
    if (Math.floor(num / 100) !== q) {
      wrong += 1
      if (examples.length < 6) examples.push(`cents=${c} pct=${p} num=${num} floatFloor=${Math.floor(num / 100)} exact=${q}`)
    }
  }
}
console.log('Math.floor(num/100) disagreements over 30M pairs:', wrong)
console.log(examples.join('\n'))

// Same question for an arbitrary divisor (the shares mode).
let wrong2 = 0
const ex2 = []
for (let cents = 1; cents <= 20000; cents += 1) {
  for (let s = 1; s <= 9; s += 1) {
    for (let total = 1; total <= 30; total += 1) {
      const num = cents * s
      let q = 0
      while ((q + 1) * total <= num) q += 1
      if (Math.floor(num / total) !== q) {
        wrong2 += 1
        if (ex2.length < 4) ex2.push(`cents=${cents} s=${s} total=${total} floatFloor=${Math.floor(num / total)} exact=${q}`)
      }
    }
  }
}
console.log('shares-mode float-floor disagreements:', wrong2, ex2.join(' | '))

// With correct floors, is the remainder always <= participant count?
let over = 0
for (let c = 1; c <= 5000; c += 1) {
  const pcts = [33, 33, 34]
  const floors = pcts.map((p) => {
    const num = c * p
    let q = 0
    while ((q + 1) * 100 <= num) q += 1
    return q
  })
  const rem = c - sumCents(floors)
  if (rem > 3 || rem < 0) over += 1
}
console.log('cases where a correct floor leaves remainder outside 0..n:', over)


